 static void entry(ZipOutputStream out,Count count,String name,byte[] bytes,boolean stored)throws Exception{ZipEntry entry=new ZipEntry(name);entry.setTime(315619200000L);if(stored){entry.setMethod(ZipEntry.STORED);entry.setSize(bytes.length);entry.setCompressedSize(bytes.length);CRC32 crc=new CRC32();crc.update(bytes);entry.setCrc(crc.getValue());int pad=(int)((4-(count.count+30+name.getBytes("UTF-8").length+4)%4)%4);byte[] extra=new byte[4+pad];extra[0]=53;extra[1]=(byte)217;extra[2]=(byte)pad;entry.setExtra(extra);}out.putNextEntry(entry);out.write(bytes);out.closeEntry();}
